script:
(function () {
  'use strict';
  // Cash-out refinance to pay off debts vs keeping the current mortgage and debts.
  //   Current mortgage payment M = B x i / (1 - (1 + i)^-n), i = rate / 12, n = months left (B / n at 0%),
  //   rounded to the cent. Each month: interest = balance x rate / 12 (to the cent), then the payment;
  //   debts are paid at their own monthly payment until cleared, the mortgage on its schedule.
  //   New loan A = mortgage balance + debts + closing costs when financed (else costs paid in cash).
  //   Refinance payment P = level payment on A over the new term (to the cent); the last payment clears.
  //   "Same total payment": today's mortgage + debt payments (or P if higher) paid into A until it is gone.
  //   Total cost = interest + closing costs. Mortgage-part interest = the new loan's interest on the old
  //   mortgage balance alone; the debts' part is the rest. Loan-to-value = A / home value.
  // Verified in Node (scratchpad b6mtg/mc.test.js): $280,000 at 4.5% over 25 years -> $1,556.33
  //   (closed form); new loan $280,000 + $38,000 + $7,000 = $325,000 at 6.5% over 30 years ->
  //   $2,054.22 (closed form); its total interest $414,520.40 is within $2 of 360 x P - A (last-payment
  //   rounding); a $12,000 card at 23.99% paying $360 takes 56 months (independent loop); paying
  //   today's $2,626.33 into the new loan takes 206 months, the closed form n = -ln(1 - Ai/P) /
  //   ln(1 + i) = 205.4 rounded up; LTV $325,000 / $450,000 = 72.2%;
  //   0% rates, a zero mortgage balance, a payment below a debt's interest and an over-limit loan are
  //   handled; no NaN/Infinity on blank or bad input.
  var MAX_MONTHS = 1200, ROWS = 5;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function cents(x) { return Math.round(x * 100) / 100; }

  function read(id, blankAs) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAs === undefined ? NaN : blankAs;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function levelPayment(amount, apr, months) {
    if (amount <= 0) return 0;
    var r = apr / 12;
    return cents(r === 0 ? amount / months : r * amount / (1 - Math.pow(1 + r, -months)));
  }

  // Loans run side by side. Each: { bal, apr, pay, last } (last = month the payment must clear it, or 0).
  function simulate(loans) {
    var bals = loans.map(function (l) { return l.bal; }), interest = loans.map(function () { return 0; });
    var years = [], yearPaid = 0, paidTotal = 0, done = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var owed = 0;
      for (var k = 0; k < loans.length; k++) {
        if (bals[k] <= 0) continue;
        var it = cents(bals[k] * loans[k].apr / 12);
        bals[k] += it;
        var pay = loans[k].last === m ? bals[k] : Math.min(loans[k].pay, bals[k]);
        bals[k] -= pay;
        if (bals[k] < 0.005) bals[k] = 0;
        interest[k] += it; yearPaid += pay; paidTotal += pay;
        owed += bals[k];
      }
      if (m % 12 === 0 || owed === 0) { years.push({ paid: yearPaid, owed: owed }); yearPaid = 0; }
      if (owed === 0) { done = m; break; }
    }
    return { months: done || MAX_MONTHS, ok: done > 0, interest: interest, totalInterest: interest.reduce(function (s, x) { return s + x; }, 0), paid: paidTotal, years: years };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function pct(x) { return (Math.round(x * 10000) / 100) + '%'; }
  function signedMoney(x) { return Math.abs(x) < 0.005 ? money.format(0) : (x > 0 ? '+' : '−') + money.format(Math.abs(x)); }

  function readDebts() {
    var out = [], bad = false;
    for (var k = 1; k <= ROWS; k++) {
      var b = el('mcBal' + k), a = el('mcApr' + k), p = el('mcPay' + k);
      var bal = read('mcBal' + k, 0), apr = read('mcApr' + k, 0), pay = read('mcPay' + k, 0);
      if (String(b.value).trim() === '' || bal === 0) { [b, a, p].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); }); continue; }
      var badB = isNaN(bal) || bal < 0 || bal > 1e8, badA = isNaN(apr) || apr < 0 || apr > 100, badP = isNaN(pay) || pay <= 0 || pay > 1e7;
      if (!badB && !badA && !badP && pay <= cents(bal * apr / 1200)) badP = true;
      b.setAttribute('aria-invalid', String(badB)); a.setAttribute('aria-invalid', String(badA)); p.setAttribute('aria-invalid', String(badP));
      if (badB || badA || badP) { bad = true; continue; }
      out.push({ bal: bal, apr: apr / 100, pay: pay, last: 0 });
    }
    return { bad: bad, debts: out };
  }

  function clearResults() {
    ['mcNewPay', 'mcChange', 'mcSaved', 'mcLtv'].forEach(function (id) { setText(id, '–'); setText(id + 'Note', ''); });
    ['mcLoanAmt', 'mcMortKeep', 'mcMortRefi', 'mcDebtKeep', 'mcDebtRefi'].forEach(function (id) { setText(id, '–'); });
    el('mcVerdict').hidden = true;
    el('mcLimit').hidden = true;
    el('mcCompare').innerHTML = '';
    el('mcYears').innerHTML = '';
  }

  function update() {
    var value = read('mcValue'), mort = read('mcMort', 0), mRate = read('mcMortRate'), mYears = read('mcMortYears'),
        nRate = read('mcNewRate'), nYears = read('mcNewYears'), costs = read('mcCosts', 0), limit = read('mcMaxLtv'),
        financed = el('mcFinance').checked;
    var input = readDebts();
    var msg = '';
    if (isNaN(value) || value <= 0 || value > 1e9) msg = 'Enter a home value above $0.';
    else if (isNaN(mort) || mort < 0 || mort > 1e9) msg = 'Enter a mortgage balance of $0 or more.';
    else if (mort > 0 && (isNaN(mRate) || mRate < 0 || mRate > 30)) msg = 'Enter your current mortgage rate, from 0% to 30%.';
    else if (mort > 0 && (isNaN(mYears) || mYears < 1 || mYears > 40 || mYears % 1 !== 0)) msg = 'Enter 1 to 40 whole years left on your mortgage.';
    else if (input.bad) msg = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and monthly payments above each debt’s monthly interest.';
    else if (!input.debts.length) msg = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(nRate) || nRate < 0 || nRate > 30) msg = 'Enter a new mortgage rate from 0% to 30%.';
    else if (isNaN(nYears) || nYears < 1 || nYears > 40 || nYears % 1 !== 0) msg = 'Enter a new loan term of 1 to 40 whole years.';
    else if (isNaN(costs) || costs < 0 || costs > 1e7) msg = 'Enter closing costs of $0 or more.';
    else if (isNaN(limit) || limit <= 0 || limit > 100) msg = 'Enter a cash-out limit above 0% and up to 100%.';
    var error = el('mcError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); setText('mcMortPayHint', ''); return; }

    var debts = input.debts, mMonths = mort > 0 ? mYears * 12 : 0, mr = mort > 0 ? mRate / 100 : 0;
    var mPay = mort > 0 ? levelPayment(mort, mr, mMonths) : 0;
    setText('mcMortPayHint', mort > 0 ? 'Your current principal and interest payment works out to ' + money.format(mPay) + ' a month.' : 'No current mortgage: the refinance becomes a new cash-out mortgage.');
    var D = debts.reduce(function (s, d) { return s + d.bal; }, 0);
    var debtPay = debts.reduce(function (s, d) { return s + d.pay; }, 0);
    var curPay = mPay + debtPay;

    var keepLoans = (mort > 0 ? [{ bal: mort, apr: mr, pay: mPay, last: mMonths }] : []).concat(debts);
    var keep = simulate(keepLoans);
    var keepMortInt = mort > 0 ? keep.interest[0] : 0, keepDebtInt = keep.totalInterest - keepMortInt;

    var nr = nRate / 100, nMonths = nYears * 12;
    var A = mort + D + (financed ? costs : 0);
    var P = levelPayment(A, nr, nMonths);
    var refi = simulate([{ bal: A, apr: nr, pay: P, last: nMonths }]);
    var refiMortOnly = mort > 0 ? simulate([{ bal: mort, apr: nr, pay: levelPayment(mort, nr, nMonths), last: nMonths }]).totalInterest : 0;
    var samePay = Math.max(curPay, P);
    var same = simulate([{ bal: A, apr: nr, pay: samePay, last: 0 }]);

    var keepCost = keep.totalInterest, refiCost = refi.totalInterest + costs, sameCost = same.totalInterest + costs;

    setText('mcNewPay', money.format(P));
    setText('mcNewPayNote', 'Borrowing ' + money0.format(A) + ' over ' + nYears + ' years at ' + nRate + '%.');
    setText('mcChange', signedMoney(P - curPay));
    setText('mcChangeNote', (P <= curPay ? 'Less' : 'More') + ' than the ' + money.format(curPay) + ' you pay today (' + money.format(mPay) + ' mortgage + ' + money.format(debtPay) + ' debts).');
    var saving = keepCost - refiCost;
    setText('mcSavedLabel', saving >= 0 ? 'Total saved' : 'Extra total cost');
    setText('mcSaved', money.format(Math.abs(saving)));
    setText('mcSavedNote', 'Interest plus closing costs, paying the new loan on its schedule.');
    var ltv = A / value, room = value * limit / 100;
    setText('mcLtv', (ltv * 100).toFixed(1) + '%');
    setText('mcLtvNote', 'A cash-out loan of up to about ' + money0.format(room) + ' fits the ' + limit + '% limit.');
    var lim = el('mcLimit');
    lim.hidden = A <= room + 0.005;
    if (!lim.hidden) setText('mcLimitText', 'A ' + money0.format(A) + ' loan is ' + (ltv * 100).toFixed(1) + '% of the home’s value, above the ' + limit + '% limit. ' + (room - mort - (financed ? costs : 0) > 0 ? 'You may be able to take out only about ' + money0.format(room - mort - (financed ? costs : 0)) + ' to pay off debts.' : 'There is no room to take cash out at this limit.'));

    var verdict = el('mcVerdict');
    verdict.hidden = false;
    var sameSaving = keepCost - sameCost;
    if (saving >= 0) {
      verdict.className = 'callout callout-success mt-5';
      setText('mcVerdictTitle', 'Refinancing costs less overall');
      setText('mcVerdictText', 'You save ' + money.format(saving) + ' in interest and fees and are debt-free ' + (refi.months <= keep.months ? duration(keep.months - refi.months) + ' sooner.' : duration(refi.months - keep.months) + ' later.') + (sameSaving > saving ? ' Keep paying ' + money.format(samePay) + ' a month and you finish in ' + duration(same.months) + ', saving ' + money.format(sameSaving) + '.' : ''));
    } else {
      verdict.className = 'callout callout-warning mt-5';
      setText('mcVerdictTitle', P < curPay ? 'Lower payment, higher total cost' : 'Refinancing costs more');
      setText('mcVerdictText', 'Over ' + duration(refi.months) + ' the refinance costs ' + money.format(-saving) + ' more than keeping your mortgage and paying the debts as you do.' + (refiMortOnly > keepMortInt ? ' Refinancing your existing mortgage balance alone adds ' + money.format(refiMortOnly - keepMortInt) + ' in interest.' : '') + (sameSaving > 0 ? ' Paying ' + money.format(samePay) + ' a month instead clears it in ' + duration(same.months) + ' and saves ' + money.format(sameSaving) + '.' : ''));
    }

    setText('mcLoanAmt', money.format(A) + (financed && costs > 0 ? ' (incl. ' + money0.format(costs) + ' closing costs)' : ''));
    setText('mcMortKeep', money.format(keepMortInt));
    setText('mcMortRefi', money.format(refiMortOnly));
    setText('mcDebtKeep', money.format(keepDebtInt));
    setText('mcDebtRefi', money.format(Math.max(0, refi.totalInterest - refiMortOnly)) + (financed && costs > 0 ? ' (incl. interest on the costs)' : ''));

    var weighted = keepLoans.reduce(function (s, l) { return s + l.bal * l.apr; }, 0) / (mort + D);
    function row(cells) { return '<tr>' + cells.map(function (c) { return '<td>' + c + '</td>'; }).join('') + '</tr>'; }
    el('mcCompare').innerHTML = [
      row(['Monthly payment', money.format(curPay) + ' now, falling as debts are paid', money.format(P), money.format(samePay)]),
      row(['Interest rate', pct(weighted) + ' average (balance-weighted)', pct(nr), pct(nr)]),
      row(['Time to debt-free', duration(keep.months), duration(refi.months), duration(same.months)]),
      row(['Total interest', money.format(keep.totalInterest), money.format(refi.totalInterest), money.format(same.totalInterest)]),
      row(['Closing costs', money.format(0), money.format(costs), money.format(costs)]),
      row(['Total cost (interest + costs)', money.format(keepCost), money.format(refiCost), money.format(sameCost)]),
      row(['Debt secured by your home', money0.format(mort), money0.format(A), money0.format(A)])
    ].join('');

    var html = [], n = Math.max(keep.years.length, refi.years.length);
    for (var y = 0; y < n; y++) {
      var a = keep.years[y], b = refi.years[y];
      html.push(row([String(y + 1), a ? money.format(a.paid) : money.format(0), a ? money.format(a.owed) : money.format(0),
        b ? money.format(b.paid) : money.format(0), b ? money.format(b.owed) : money.format(0)]));
    }
    el('mcYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('mcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
